INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (334909, 14503, 'Amar Ujala', 'hi', 'Batwara 1947: सनी और प्रीति ने फैंस को थिएटर में दिया सरप्राइज, बॉबी देओल भी आए नजर; ये सितारे भी हुए शामिल', 'https://www.amarujala.com/entertainment/bollywood/batwara-1947-actor-sunny-deol-preity-zinta-javed-akhtar-surprise-fans-in-theatre-2026-08-14', 'आज आमिर खान प्रोडक्शन की फिल्म ‘बंटवारा 1947’ सिनेमाघरों में रिलीज हुई। फैंस को सरप्राइज देने के लिए फिल्म के लीड एक्टर सनी देओल और बाकी टीम मुंबई के एक थिएटर में पहुंचीं। देखिए, यहां और कौन-कौन नजर आया।', '', '2026-08-14T04:40:03+00:00', '2026-08-14T18:09:47.946159'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
